    sse_encode_String(self.fingerprintSha256, serializer);
    sse_encode_bool(self.isEncrypted, serializer);
  }

  @protected
  void sse_encode_list_prim_u_8_strict(
      Uint8List self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    sse_encode_i_32(self.length, serializer);
    serializer.buffer.putUint8List(self);
  }

  @protected
  void sse_encode_opencode_connect_config(
      OpencodeConnectConfig self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    sse_encode_String(self.sessionId, serializer);
    sse_encode_ssh_connect_config(self.sshConfig, serializer);
    sse_encode_opt_String(self.remoteWorkdir, serializer);
    sse_encode_opt_String(self.customOpencodePath, serializer);
    sse_encode_opt_box_autoadd_u_16(self.preferredLocalPort, serializer);
